import { create } from 'zustand'
import { persist, devtools } from 'zustand/middleware';
import { immer } from 'zustand/middleware/immer';
import * as cartApi from '../api/cartApi'

export const useCartStore = create(
  devtools(
    persist(
      immer((set, get) => ({
        items: [],
        count: 0,
        total: 0,
        isOpen: false,
        // API: загрузка корзины
        fetchCart: async () => {
          console.log('🛒 fetchCart called');
          try {
            const data = await cartApi.getCartItems();
            console.log('🛒 fetchCart data received:', data);
            set((state) => {
              // Убедимся, что data и data.items существуют и являются массивом
              const itemsArray = (data && Array.isArray(data.items)) ? data.items : [];
              state.items = itemsArray;

              // Пересчитываем count и total на основе itemsArray
              state.count = (data && data.count !== undefined) 
                ? data.count 
                : itemsArray.reduce((sum, item) => sum + (item.quantity || 0), 0);
              
              state.total = (data && data.total !== undefined) 
                ? parseFloat(data.total) 
                : itemsArray.reduce((sum, item) => sum + ((item.quantity || 0) * parseFloat(item.price || 0)), 0);

              console.log('🛒 Cart state updated:', { 
                itemsLength: state.items.length, 
                count: state.count, 
                total: state.total,
                backendData: data // Логируем весь ответ от бэкенда для отладки
              });
            });
          } catch (error) {
            console.error('🛒 Error in fetchCart:', error);
            alert(error.message || 'Ошибка загрузки корзины');
          }
        },
        // API: добавить товар
        addToCart: async (productId, sizeId = null, quantity = 1) => {
          console.log('🛒 cartStore.addToCart called:', { productId, sizeId, quantity });
          try {
            const result = await cartApi.addCartItem(productId, quantity, sizeId);
            console.log('🛒 cartApi.addCartItem result:', result);
            
            // Оптимизация: обновляем корзину сразу после добавления
            await get().fetchCart();
            console.log('🛒 Cart refreshed after adding item');
            return true;
          } catch (error) {
            console.error('🛒 Error in cartStore.addToCart:', error);
            // Передаем ошибку дальше, чтобы AddToCartButton мог показать уведомление
            throw error;
          }
        },
        // API: добавить предзаказ
        addPreorderToCart: async (preorderId, sizeId = null, quantity = 1) => {
          console.log('🛒 cartStore.addPreorderToCart called:', { preorderId, sizeId, quantity });
          try {
            const result = await cartApi.addPreorderItem(preorderId, quantity, sizeId);
            console.log('🛒 cartApi.addPreorderItem result:', result);
            
            // Оптимизация: обновляем корзину сразу после добавления
            await get().fetchCart();
            console.log('🛒 Cart refreshed after adding preorder');
            return true;
          } catch (error) {
            console.error('🛒 Error in cartStore.addPreorderToCart:', error);
            // Передаем ошибку дальше, чтобы AddToPreorderButton мог показать уведомление
            throw error;
          }
        },
        // API: обновить количество
        updateQuantity: async (itemId, quantity) => {
          try {
            await cartApi.updateCartItem(itemId, quantity);
            await get().fetchCart();
          } catch (error) {
            alert(error.message || 'Ошибка обновления количества');
          }
        },
        // API: удалить товар
        removeFromCart: async (itemId) => {
          try {
            await cartApi.removeCartItem(itemId);
            await get().fetchCart();
          } catch (error) {
            alert(error.message || 'Ошибка удаления из корзины');
          }
        },
        // API: очистить корзину
        clearCart: async () => {
          try {
            await cartApi.clearCart();
            set((state) => { state.items = []; state.count = 0; state.total = 0; });
          } catch (error) {
            alert(error.message || 'Ошибка очистки корзины');
          }
        },
        // UI: открыть/закрыть корзину
        toggleCart: () => set((state) => { state.isOpen = !state.isOpen }),
      })),
      { name: 'cart-storage' }
    )
  )
)