import axios from './axiosInstance';

export async function getCartItems() {
  console.log('🛒 cartApi.getCartItems called');
  const sessionId = localStorage.getItem('cart_session_id');
  console.log('🛒 Frontend session ID:', sessionId);
  
  // 1. Получаем основную информацию о корзине
  const { data: cartData } = await axios.get('/api/cart/items/');
  console.log('🛒 cartApi.getCartItems initial response:', cartData);

  // 2. Проверяем, является ли `items` ссылкой
  if (cartData && typeof cartData.items === 'string' && cartData.items.startsWith('http')) {
    try {
      // 3. Если это ссылка, загружаем сами товары
      console.log(`🛒 Following cart items link: ${cartData.items}`);
      const { data: itemsData } = await axios.get(cartData.items);
      console.log('🛒 Fetched cart items:', itemsData);
      
      // 4. Собираем и возвращаем полный объект корзины
      return {
        ...cartData,
        items: Array.isArray(itemsData) ? itemsData : [], // Убедимся, что items - это массив
        // Если бэкенд возвращает count и total в основном запросе, они сохранятся.
        // Если нет, cartStore их рассчитает.
      };
    } catch (error) {
      console.error('🛒 Failed to fetch items from link:', error);
      // Возвращаем исходные данные с пустым массивом items в случае ошибки
      return { ...cartData, items: [] };
    }
  }

  // Если cartData.items - это уже массив или что-то другое, возвращаем как есть
  console.log('🛒 cartApi.getCartItems final data:', cartData);
  return cartData;
}

export async function addCartItem(productId, quantity = 1, sizeId = null) {
  const requestData = { product: productId, quantity };
  if (sizeId) {
    requestData.size = sizeId;
  }
  const sessionId = localStorage.getItem('cart_session_id');
  console.log('🛒 cartApi.addCartItem request:', requestData);
  console.log('🛒 Frontend session ID for POST:', sessionId);
  const { data } = await axios.post('/api/cart/add/', requestData);
  console.log('🛒 cartApi.addCartItem response:', data);
  return data;
}

export async function addPreorderItem(preorderId, quantity = 1, sizeId = null) {
  const requestData = { preorder: preorderId, quantity };
  if (sizeId) {
    requestData.size = sizeId;
  }
  const sessionId = localStorage.getItem('cart_session_id');
  console.log('🛒 cartApi.addPreorderItem request:', requestData);
  console.log('🛒 Frontend session ID for POST:', sessionId);
  const { data } = await axios.post('/api/cart/add_preorder/', requestData);
  console.log('🛒 cartApi.addPreorderItem response:', data);
  return data;
}

export async function updateCartItem(itemId, quantity) {
  const { data } = await axios.put(`/api/cart/update/${itemId}/`, { quantity });
  return data;
}

export async function removeCartItem(itemId) {
  const { data } = await axios.delete(`/api/cart/remove/${itemId}/`);
  return data;
}

export async function clearCart() {
  const { data } = await axios.post('/api/cart/clear/');
  return data;
}

// Применение промокода к корзине
export async function applyPromoCode(code) {
  const { data } = await axios.post('/api/cart/apply-promo/', { code });
  return data;
}

// Удаление промокода из корзины
